// Fixture batch 092: construction planes cut by operations. Generated by tools/fixtures/gen-batch-092.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

// The bodies a query finds: how many, how many construction, and their areas.
function constructionProbe(context is Context, bodies is Query) returns map
{
    return { "all" : evaluateQueryCount(context, bodies),
             "construction" : evaluateQueryCount(context, qConstructionFilter(bodies, ConstructionObject.YES)),
             "areas" : mapArray(evaluateQuery(context, bodies), function(b) { return roundToPrecision(evArea(context, { "entities" : b }) / millimeter ^ 2, 3); }) };
}

// extrude: a 40 × 40 construction plane cut by a 30 × 30 extrude through it
export function c001(context is Context, id is Id)
{
    opPlane(context, id + "p1", { "plane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)), "width" : 40 * millimeter, "height" : 40 * millimeter });
    const c1 = newSketchOnPlane(context, id + "c1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(c1, "r1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(30, 30) * millimeter });
    skSolve(c1);
    extrude(context, id + "cut", { "entities" : qSketchRegion(id + "c1"), "endBound" : BoundingType.BLIND, "depth" : 5 * millimeter, "symmetric" : true, "operationType" : NewBodyOperationType.REMOVE, "defaultScope" : false, "booleanScope" : qCreatedBy(id + "p1", EntityType.BODY) });
    return { "plane" : constructionProbe(context, qCreatedBy(id + "p1", EntityType.BODY)) };
}

